def ascii_value_string(str1):
    """Write a function to find the ascii value of total characters in a string.

    Return the total ASCII value of all characters divided by the
    number of characters, using integer division. For example, the
    ASCII values of "python" sum to 674, and 674 // 6 == 112.
    An empty string has an ASCII value of 0.
    """
    if not str1:
        return 0
    return sum(ord(char) for char in str1) // len(str1)
